def rule_page1_window_after_ein_label(doc: dict) -> list[dict]:
    """Match a small page-1 window around the IRS Employer Identification label."""
    try:
        import re
        texts = doc.get("texts", [])
        out = []
        for i, span in enumerate(texts):
            txt = (span.get("text") or "").strip()
            if span.get("page_no") == 1 and re.search(r"i\.r\.s\. employer identification no\.?|irs employer identification no\.?|employer identification no", txt, re.I):
                for s in texts[max(0, i - 3): min(len(texts), i + 4)]:
                    if s.get("page_no") == 1:
                        out.append(s)
        return out
    except Exception:
        return []

def rule_page1_ein_or_state_labels(doc: dict) -> list[dict]:
    """Match page-1 spans containing the state/jurisdiction or IRS Employer Identification label text."""
    try:
        import re
        out = []
        for span in doc.get("texts", []):
            text = (span.get("text") or "") + " " + (span.get("text_span") or "")
            if span.get("page_no") == 1 and re.search(r"state\s+or\s+other\s+jurisdiction|i\.?r\.?s\.?\s+employer\s+identification|irs\s+employer\s+identification", text, re.I):
                out.append(span)
        return out
    except Exception:
        return []

def rule_page1_ein_value_followed_by_ein_label(doc: dict) -> list[dict]:
    """Match page-1 spans immediately preceding an IRS Employer Identification label span."""
    try:
        import re
        texts = doc.get("texts", [])
        out = []
        for i, span in enumerate(texts[:-1]):
            nxt = texts[i + 1]
            nxt_text = (nxt.get("text") or "").strip()
            cur_text = (span.get("text") or "").strip()
